def gate_hurwitz():
    """Euler-Maclaurin zeta(s,1) against plain summation, where both are valid."""
    pts = [2.5 + 0.0j, 3.0 + 1.0j, 4.0 - 2.0j, 2.2 + 5.0j]
    got = hurwitz(np.array(pts), 1.0)
    worst = max(abs(g - _zeta_direct(p)) / abs(_zeta_direct(p))
                for g, p in zip(got, pts))
    return worst < 1e-11, {"worst_rel": worst}

